---初始化装备预设列表
function CardProgressionEquipmentPresetDialog:InitEquipmentDiySuits()
    local equipmentDiySuits = clone(checkTable(PlayerComponent.playerDojo.equipmentDiySuits))

    for _, v in ipairs(equipmentDiySuits) do
        local equipmentList = string.split(v.equipments, ",")
        local filter = {['0'] = true}
        for _, playerEquipmentId in ipairs(equipmentList) do
            if checkInt(playerEquipmentId) > 0 then
                local equipDojo = EquipComponent:GetEquipById(playerEquipmentId) or {}
                local equipVo = CardConfMgr:GetInstance():GetEquipVoById(equipDojo.equipmentId)
                if isNotNull(equipVo) then
                    filter[tostring(equipVo.suitId)] = true
                end
            end
        end
        v.filter = filter
    end
    
    self:SetEquipmentDiySuits(equipmentDiySuits)
end

