---删除套装预设点击事件
function CardProgressionEquipmentPresetDialog:BtnDeleteOnClickHandler()
    local suitData = self:GetSuitData()
    local suitId = checkInt(suitData.suitId)
    GameUtils.Request(Interfaces.OverseaEquipmentDeleteDiySuit, {suitId = suitId}, function (request,response)
        if checkNumber(response.errCode) ~= 0 then return end

        -- 更新本地数据
        local equipmentDiySuits = checkTable(PlayerComponent.playerDojo.equipmentDiySuits)
        for i, v in ipairs(equipmentDiySuits) do
            if checkInt(v.suitId) == suitId then
                table.remove(equipmentDiySuits, i)
                break
            end
        end
        GameUtils.Toast(localize("删除成功"))
        self:RefreshView()
    end)
end

