---使用装备预设点击事件
function CardProgressionEquipmentPresetDialog:BtnSwitchOnClickHandler()
    local cardDojo = self:GetCardDojo()
    local equipmentList = self:GetEquipmentList()

    local usedTable = {}
    for i, v in ipairs(equipmentList) do
        if checkInt(v) > 0 then
            local equippingCardId = checkInt(EquipComponent:GetCardOnEquipByEquipId(v))
            if equippingCardId > 0 and equippingCardId ~= cardDojo.id then
                table.insert(usedTable, v)
            end
        end
    end
    
    local function func()
        local equipIdList = {}
        for i = 1, CardProgressionConstants.EquipmentNum do
                local playerEquipmentId = equipmentList[i]
            local equipDojo = EquipComponent:GetEquipById(playerEquipmentId)
            if isNull(equipDojo) then
                playerEquipmentId = 0
            end
            EquipComponent:AddCardOnEquip(cardDojo.id, playerEquipmentId, i)
            equipIdList[tostring(i)] = playerEquipmentId
        end
        CardProgressionMgr:RequestOverseaEquipmentEquip({
            playerCardId = cardDojo.id, equipment = table.serialize(equipIdList)
        }, function ()
            GameUtils.Toast(localize("装备成功"))
        end)
    end

    if #usedTable > 0 then
        local consume = {}
        for _, v in ipairs(usedTable) do
            local temp = {}
            local equipDojo = EquipComponent:GetEquipById(v)
            temp.goodsId = equipDojo.equipmentId
            temp.id = equipDojo.id
            table.insert(consume, temp)
        end
        GameUtils.SecondConfirm(localize("有_num_件装备正在被穿戴，是否继续装备？", {_num_ = #usedTable}),function()
            func()
        end,nil, nil, 11, consume)
    else
        func()
    end
end

