end

---检查是否当前套装
function CardProgressionEquipmentPresetDialog:CheckCurrentSuit()
    local cardDojo = self:GetCardDojo()
    local equipmentList = self:GetEquipmentList()
    for i = 1, CardProgressionConstants.EquipmentNum do
        if checkInt(cardDojo['equipment' .. i]) ~= checkInt(equipmentList[i]) then
            return false
        end
    end 
    return true
end
