---获取格式化装备字符串
function CardProgressionEquipmentPresetDialog:GetFormattingEquipmentStr()
    local equipmentList = self:GetEquipmentList()
    local str = ""
    for i, v in ipairs(equipmentList) do
        str = str .. v
        if i < #equipmentList then
            str = str .. ","
        end
    end
    return str
end

