function CardProgressionEquipmentPresetDialog:GetSuitData()
    local equipmentStr = self:GetFormattingEquipmentStr()
    local suits = self:GetEquipmentDiySuits()
    for i, v in ipairs(suits) do
        if v.equipments == equipmentStr then
            return v
        end
    end
    return nil
end

---设置玩家卡牌id
function CardProgressionEquipmentPresetDialog:SetPlayerCardId(playerCardId)
    self._playerCardId = checkInt(playerCardId)
end

---获取玩家卡牌id
function CardProgressionEquipmentPresetDialog:GetPlayerCardId()
    return self._playerCardId
end

---设置装备预设上限
function CardProgressionEquipmentPresetDialog:SetPresetUpperLimit(limit)
    self._presetUpperLimit = limit
end

---获取装备预设上限
function CardProgressionEquipmentPresetDialog:GetPresetUpperLimit()
    return self._presetUpperLimit
end
--endregion get / set

return CardProgressionEquipmentPresetDialog